/* Fullscreen Hero Global Styles */

/* Base hero container */
.hero-fullscreen {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

/* Background image/video */
.hero-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Video background */
.hero-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Overlay variations */
.hero-overlay {
  position: absolute;
  inset: 0;
}

.hero-overlay-dark {
  background: rgba(0, 0, 0, 0.5);
}

.hero-overlay-gradient {
  background: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0.3) 0%,
    transparent 50%,
    rgba(0, 0, 0, 0.7) 100%
  );
}

.hero-overlay-color {
  background: rgba(99, 102, 241, 0.7);
  mix-blend-mode: multiply;
}

/* Content container */
.hero-content {
  position: relative;
  z-index: 10;
  text-align: center;
  padding: 1rem;
  max-width: 64rem;
}

/* Scroll indicator animation */
@keyframes hero-bounce {
  0%, 100% {
    transform: translateY(0) translateX(-50%);
  }
  50% {
    transform: translateY(10px) translateX(-50%);
  }
}

.hero-scroll-indicator {
  position: absolute;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  animation: hero-bounce 2s infinite;
}

/* Parallax effect */
.hero-parallax {
  transform: translateZ(0);
  will-change: transform;
}

/* Ken Burns effect for images */
@keyframes kenburns {
  0% {
    transform: scale(1);
  }
  100% {
    transform: scale(1.1);
  }
}

.hero-kenburns .hero-bg {
  animation: kenburns 20s ease-out forwards;
}

.hero-fullscreen-filter { filter: brightness(1.05) contrast(1.02); }

.hero-fullscreen-focus { outline: 2px solid var(--hero-fullscreen-primary, currentColor); outline-offset: 2px; }

/* Additional techniques */
:root { --hero-fullscreen-radius: 0.75rem; --hero-fullscreen-transition: 0.3s ease; }

.hero-fullscreen-divider::after { content: ""; display: block; width: 3rem; height: 2px; margin-top: 0.5rem; background: var(--hero-fullscreen-primary, currentColor); }

.hero-fullscreen-slant { clip-path: polygon(0 0, 100% 0, 100% calc(100% - 3rem), 0 100%); }

.hero-fullscreen-glass { backdrop-filter: blur(8px) saturate(150%); -webkit-backdrop-filter: blur(8px) saturate(150%); }
